def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,x): p.write_text(json.dumps(x,indent=2,sort_keys=True,default=str)+'\n')
def raw(y): return pd.read_csv(ROOT/f'data/raw/oracles_elixir/{y}_LoL_esports_match_data_from_OraclesElixir.csv',low_memory=False)
def series_from_raw(y,league,after,before):
 d=raw(y); d=d[(d.league==league)&(d.position=='team')&(pd.to_datetime(d.date,utc=True)>=pd.Timestamp(after,tz='UTC'))&(pd.to_datetime(d.date,utc=True)<pd.Timestamp(before,tz='UTC'))].copy()
 d['date']=pd.to_datetime(d.date,utc=True); d=d.drop_duplicates(['gameid','teamname']); games=d.groupby('gameid').agg(date=('date','first'),teams=('teamname',lambda z:tuple(sorted(z))),game=('game','first')).reset_index(); games=games.sort_values('date')
 rows=[]; prior={}
 for g in games.itertuples():
  key=g.teams; last=prior.get(key)
  if last is None or (g.date-last['last']).total_seconds()>5*3600 or g.game<=last['game']:
   prior[key]={'id':f'{y}:{league}:{g.date.isoformat()}:{"|".join(key)}','last':g.date,'game':g.game,'games':[]}; last=prior[key]
  last['games'].append(g.gameid); last['last']=g.date; last['game']=g.game
 for x in prior.values():
  if len(x['games']) in (2,3): rows.append({'series_id':x['id'],'date':x['last'].date().isoformat(),'games_played':len(x['games']),'team_a':x['id'].split(':')[-1].split('|')[0],'team_b':x['id'].split(':')[-1].split('|')[1]})
 return pd.DataFrame(rows)
