 hist=pd.concat(all,ignore_index=True); hist=hist[['series_id','date','season','split','stage','team_a','team_b','best_of','games_played','source_rule']]; hist.to_csv(out/'stage-10d-r12f-r2-bo3-series-history.csv',index=False);pd.DataFrame(coverage).to_csv(out/'stage-10d-r12f-r2-bo3-period-coverage.csv',index=False)
