 pred=players[['player','role','team','opponent','series_count','price','per_game_prediction','expected_games_period','weekly_prediction','recent_fantasy_mean_5','projected_starter','round_name','roster_lock']].copy();pred['avg_games_per_bo3']=avg;pred['overall_rank']=pred.weekly_prediction.rank(method='first',ascending=False).astype(int);pred['role_rank']=pred.groupby('role').weekly_prediction.rank(method='first',ascending=False).astype(int);pred=pred.sort_values('overall_rank');pred.to_csv(out/'stage-10d-r12f-r2-week5-player-predictions.csv',index=False);dump(out/'stage-10d-r12f-r2-week5-prediction-accounting.json',{'max_abs_error':float((pred.weekly_prediction-pred.per_game_prediction*pred.expected_games_period).abs().max())})
